n, m = map(int, input().split())
aim_am_lis = list(map(int, input().split()))
am_lis = []
for i in range(n):
    am_lis.append(list(map(int, input().split())))

# Calculate the sum of each nutrient type across all foods
nutrient_sums = [0] * m
for food in am_lis:
    for j in range(m):
        nutrient_sums[j] += food[j]

cnt = 0
for i in range(m):
    if nutrient_sums[i] >= aim_am_lis[i]:
        cnt += 1

if cnt == m:
    print("Yes")
else:
    print("No")
